// Durable local budget accounting. No provider SDK, prompts, credentials or network I/O.
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, realpathSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';

export class BudgetError extends Error {
  constructor(code, message = code) { super(message); this.name = 'BudgetError'; this.code = code; }
}
const fail = (code, message) => { throw new BudgetError(code, message); };
const clone = value => JSON.parse(JSON.stringify(value));
const integer = n => Number.isSafeInteger(n) && n >= 0;
const identity = value => typeof value === 'string' && /^[A-Za-z0-9][A-Za-z0-9._:/@+-]{0,159}$/.test(value);
const keys = (value, allowed) => {
  if (!value || typeof value !== 'object' || Array.isArray(value) || Object.keys(value).some(k => !allowed.includes(k))) fail('BUDGET_INVALID_CONFIG');
};
export function projectBudgetKey(path) {
  if (typeof path !== 'string' || !path) fail('BUDGET_PROJECT_REQUIRED');
  let canonical = resolve(path);
  try { canonical = realpathSync.native(canonical); } catch { fail('BUDGET_PROJECT_NOT_FOUND'); }
  if (process.platform === 'win32') canonical = canonical.toLowerCase();
  return 'project:' + createHash('sha256').update(canonical).digest('hex');
}
export const privateId = value => value == null ? null : createHash('sha256').update(String(value)).digest('hex');
// Six fractional USD digits in configured amounts/rates; cost is rounded UP to nanoUSD.
function micros(value) {
  const s = String(value);
  if (!/^\d{1,12}(?:\.\d{1,6})?$/.test(s)) fail('BUDGET_INVALID_USD');
  const [whole, fraction = ''] = s.split('.');
  return BigInt(whole) * 1000000n + BigInt(fraction.padEnd(6, '0'));
}
const nanos = value => (micros(value) * 1000n).toString();
const ceil = (a, b) => (a + b - 1n) / b;
const fields = ['inputTokens', 'outputTokens', 'cacheReadTokens', 'cacheWriteTokens'];
export function normalizeUsage(raw) {
  if (!raw || typeof raw !== 'object') fail('BUDGET_INVALID_USAGE');
  const usage = {};
  for (const field of fields) {
    const n = raw[field] === undefined && field.startsWith('cache') ? 0 : raw[field];
    if (!integer(n)) fail('BUDGET_INVALID_USAGE');
    usage[field] = n;
  }
  const total = fields.reduce((sum, key) => sum + usage[key], 0);
  if (!integer(total) || (raw.totalTokens !== undefined && raw.totalTokens !== total)) fail('BUDGET_INVALID_USAGE');
  if (raw.reasoningTokens !== undefined && (!integer(raw.reasoningTokens) || raw.reasoningTokens > usage.outputTokens)) fail('BUDGET_INVALID_USAGE');
  // Reasoning is a SUBSET of output, not an additional billable category.
  return { ...usage, totalTokens: total, ...(raw.reasoningTokens === undefined ? {} : { reasoningTokens: raw.reasoningTokens }) };
}
function priceRow(raw) {
  keys(raw, ['provider', 'model', 'currency', 'inputPerMillion', 'outputPerMillion', 'cacheReadPerMillion', 'cacheWritePerMillion', 'maxTokensIncludesReasoning']);
  if (!identity(raw.provider) || !identity(raw.model) || raw.currency !== 'USD' || raw.maxTokensIncludesReasoning !== true) fail('BUDGET_INVALID_PRICE');
  const rates = {};
  for (const [name, field] of Object.entries({ input: 'inputPerMillion', output: 'outputPerMillion', cacheRead: 'cacheReadPerMillion', cacheWrite: 'cacheWritePerMillion' })) rates[name] = micros(raw[field]).toString();
  return { provider: raw.provider, model: raw.model, currency: 'USD', rates, maxTokensIncludesReasoning: true, provenance: 'human-configured-route-price' };
}
export function usageCostNanoUsd(usage, price) {
  if (!price) return null;
  let sum = 0n;
  for (const [field, rate] of [['inputTokens', 'input'], ['outputTokens', 'output'], ['cacheReadTokens', 'cacheRead'], ['cacheWriteTokens', 'cacheWrite']]) sum += ceil(BigInt(usage[field]) * BigInt(price.rates[rate]), 1000n);
  return sum.toString();
}
function upperCost(input, output, price) {
  if (!price) return null;
  // Cache partition is not known until the response: reserve ALL input at the highest input/cache rate.
  const inputRate = ['input', 'cacheRead', 'cacheWrite'].map(k => BigInt(price.rates[k])).reduce((a, b) => a > b ? a : b);
  return (ceil(BigInt(input) * inputRate, 1000n) + ceil(BigInt(output) * BigInt(price.rates.output), 1000n)).toString();
}
function policyValue(raw) {
  keys(raw, ['scope', 'project', 'callsEnabled', 'moneyCapUsd', 'tokenCap', 'prices']);
  if (!['global', 'project'].includes(raw.scope) || typeof raw.callsEnabled !== 'boolean') fail('BUDGET_INVALID_CONFIG');
  if (raw.moneyCapUsd === undefined || raw.tokenCap === undefined) fail('BUDGET_EXPLICIT_CAPS_REQUIRED');
  if (raw.tokenCap !== null && !integer(raw.tokenCap)) fail('BUDGET_INVALID_CONFIG');
  if (raw.scope === 'project' && raw.prices !== undefined) fail('BUDGET_GLOBAL_PRICES_ONLY');
  const prices = (raw.prices ?? []).map(priceRow);
  if (new Set(prices.map(p => JSON.stringify([p.provider, p.model]))).size !== prices.length) fail('BUDGET_DUPLICATE_PRICE');
  return { key: raw.scope === 'global' ? 'global' : projectBudgetKey(raw.project), scope: raw.scope, callsEnabled: raw.callsEnabled,
    moneyCapNanoUsd: raw.moneyCapUsd === null ? null : nanos(raw.moneyCapUsd), tokenCap: raw.tokenCap, ...(raw.scope === 'global' ? { prices } : {}) };
}
function fresh() { return { version: 1, revision: 0, policies: {}, totals: {}, reservations: {} }; }
function totalFor(state, key) { return state.totals[key] ??= { tokens: 0, costNanoUsd: '0', lifetimeTokens: 0, lifetimeCostNanoUsd: '0' }; }
function heldFor(state, key) {
  let tokens = 0, money = 0n;
  for (const r of Object.values(state.reservations)) {
    if (!r.scopes.includes(key) || r.status === 'settled' || r.status === 'acknowledged') continue;
    tokens += Math.max(0, r.reservedTokens - (r.accountedTokens ?? 0));
    const remainder = BigInt(r.reservedNanoUsd ?? '0') - BigInt(r.accountedNanoUsd ?? '0');
    money += remainder > 0n ? remainder : 0n;
  }
  if (!integer(tokens)) fail('BUDGET_COUNTER_OVERFLOW');
  return { tokens, costNanoUsd: money.toString() };
}
function blockedFor(state, key) {
  return Object.values(state.reservations).filter(r => r.scopes.includes(key) && (['uncertain', 'overrun'].includes(r.status))).map(r => r.id);
}
function addCharge(state, r, usage, cost) {
  const tokens = usage?.totalTokens ?? 0, money = BigInt(cost ?? '0');
  const deltaTokens = tokens - (r.accountedTokens ?? 0), deltaMoney = money - BigInt(r.accountedNanoUsd ?? '0');
  if (deltaTokens < 0 || deltaMoney < 0n) fail('BUDGET_USAGE_REGRESSION');
  for (const key of r.scopes) {
    const t = totalFor(state, key);
    if (!integer(t.tokens + deltaTokens) || !integer(t.lifetimeTokens + deltaTokens)) fail('BUDGET_COUNTER_OVERFLOW');
    t.tokens += deltaTokens; t.lifetimeTokens += deltaTokens;
    t.costNanoUsd = (BigInt(t.costNanoUsd) + deltaMoney).toString();
    t.lifetimeCostNanoUsd = (BigInt(t.lifetimeCostNanoUsd) + deltaMoney).toString();
  }
  r.accountedTokens = tokens; r.accountedNanoUsd = cost;
}

/** One SQLite file shared by all agent processes using this home. BEGIN IMMEDIATE serializes admission.
 * No stale-lock expiry. FULL synchronous commits; uncertain/pending exposure is NEVER reset on startup.
 * Human authority must come from trusted host code, never a tool argument, role string or chat quote.
 */
export class UsageLedger {
  #db; #authorize;
  constructor(home, { authorizeHuman = () => false } = {}) {
    if (typeof home !== 'string' || !home) fail('BUDGET_HOME_REQUIRED');
    this.file = join(resolve(home), 'usage-budget', 'ledger.sqlite');
    mkdirSync(dirname(this.file), { recursive: true, mode: 0o700 });
    this.#authorize = authorizeHuman;
    this.#db = new DatabaseSync(this.file);
    this.#db.exec('PRAGMA busy_timeout=10000; PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL;');
    this.#db.exec('CREATE TABLE IF NOT EXISTS budget_state (id INTEGER PRIMARY KEY CHECK(id=1), json TEXT NOT NULL); CREATE TABLE IF NOT EXISTS budget_audit (seq INTEGER PRIMARY KEY, json TEXT NOT NULL);');
    this.#db.prepare('INSERT OR IGNORE INTO budget_state(id,json) VALUES(1,?)').run(JSON.stringify(fresh()));
  }
  #human(principal) { if (this.#authorize(principal) !== true) fail('BUDGET_HUMAN_ONLY', 'Budget policy mutation requires a trusted direct-human host action'); }
  #transaction(operation) {
    this.#db.exec('BEGIN IMMEDIATE');
    try {
      const state = JSON.parse(this.#db.prepare('SELECT json FROM budget_state WHERE id=1').get().json);
      if (state.version !== 1) fail('BUDGET_LEDGER_VERSION');
      const audit = (type, data) => {
        const seq = Number(this.#db.prepare('SELECT COALESCE(MAX(seq),0)+1 AS seq FROM budget_audit').get().seq);
        this.#db.prepare('INSERT INTO budget_audit(seq,json) VALUES(?,?)').run(seq, JSON.stringify({ seq, time: new Date().toISOString(), type, ...data }));
      };
      const result = operation(state, audit);
      this.#db.prepare('UPDATE budget_state SET json=? WHERE id=1').run(JSON.stringify(state));
      this.#db.exec('COMMIT');
      return clone(result ?? null);
    } catch (error) { this.#db.exec('ROLLBACK'); throw error; }
  }
  configure(raw, principal) {
    this.#human(principal);
    const value = policyValue(raw);
    return this.#transaction((state, audit) => {
      value.revision = ++state.revision;
      state.policies[value.key] = value;
      totalFor(state, value.key);
      audit('policy-configured', { policy: value });
      return value;
    });
  }
  reset({ scope = 'global', project } = {}, principal) {
    this.#human(principal);
    const key = scope === 'global' ? 'global' : scope === 'project' ? projectBudgetKey(project) : fail('BUDGET_INVALID_CONFIG');
    return this.#transaction((state, audit) => {
      if (Object.values(state.reservations).some(r => r.scopes.includes(key) && !['settled', 'acknowledged'].includes(r.status))) fail('BUDGET_UNRESOLVED_RESERVATIONS');
      if (!state.policies[key]) fail('BUDGET_NOT_CONFIGURED');
      const t = totalFor(state, key);
      audit('period-reset', { scope: key, previous: t });
      t.tokens = 0; t.costNanoUsd = '0';
      return t;
    });
  }
  status() {
    return this.#transaction(state => ({ configured: !!state.policies.global, defaultCallsEnabled: false, currency: 'USD', revision: state.revision,
      scopes: Object.values(state.policies).map(policy => ({ policy, spent: totalFor(state, policy.key), held: heldFor(state, policy.key), blockedBy: blockedFor(state, policy.key) })),
      pending: Object.values(state.reservations).filter(r => !['settled', 'acknowledged'].includes(r.status)),
      unsupported: ['standalone-image-generation', 'video-generation', 'speech-and-transcription', 'provider-internal-retries', 'out-of-process-or-direct-adapter-bypass'],
      guarantee: 'local-admission-envelope-not-provider-invoice' }));
  }
  audit({ after = 0, limit = 100 } = {}) {
    if (!integer(after) || !Number.isSafeInteger(limit) || limit < 1 || limit > 1000) fail('BUDGET_INVALID_QUERY');
    return this.#db.prepare('SELECT json FROM budget_audit WHERE seq>? ORDER BY seq LIMIT ?').all(after, limit).map(row => JSON.parse(row.json));
  }
  reserve({ provider, model, projectKey, inputTokens, maxTokens, sessionId, purpose, mediaCovered = false }) {
    if (!identity(provider) || !identity(model)) fail('BUDGET_INVALID_ROUTE');
    return this.#transaction((state, audit) => {
      const global = state.policies.global;
      if (!global || !global.callsEnabled) fail('BUDGET_CALLS_DISABLED');
      if (Object.values(state.policies).some(p => p.scope === 'project') && !projectKey) fail('BUDGET_PROJECT_REQUIRED');
      const scopes = ['global', ...(projectKey && state.policies[projectKey] ? [projectKey] : [])];
      const policies = scopes.map(key => state.policies[key]);
      if (policies.some(p => !p.callsEnabled)) fail('BUDGET_CALLS_DISABLED');
      if (policies.some(p => blockedFor(state, p.key).length)) fail('BUDGET_UNCERTAIN_USAGE');
      const capped = policies.some(p => p.moneyCapNanoUsd !== null || p.tokenCap !== null);
      const price = global.prices.find(p => p.provider === provider && p.model === model) ?? null;
      if (policies.some(p => p.moneyCapNanoUsd !== null) && !price) fail('BUDGET_UNKNOWN_PRICE');
      if (capped && (!integer(inputTokens) || !Number.isSafeInteger(maxTokens) || maxTokens <= 0)) fail('BUDGET_TRUSTED_BOUND_REQUIRED');
      inputTokens ??= 0; maxTokens ??= 0;
      if (!integer(inputTokens) || !integer(maxTokens) || !integer(inputTokens + maxTokens)) fail('BUDGET_INVALID_BOUND');
      const reservedTokens = inputTokens + maxTokens, reservedNanoUsd = upperCost(inputTokens, maxTokens, price);
      for (const policy of policies) {
        const spent = totalFor(state, policy.key), held = heldFor(state, policy.key);
        if (policy.tokenCap !== null && spent.tokens + held.tokens + reservedTokens > policy.tokenCap) fail('BUDGET_TOKEN_LIMIT');
        if (policy.moneyCapNanoUsd !== null && BigInt(spent.costNanoUsd) + BigInt(held.costNanoUsd) + BigInt(reservedNanoUsd) > BigInt(policy.moneyCapNanoUsd)) fail('BUDGET_MONEY_LIMIT');
      }
      const r = { id: randomUUID(), status: 'pending', provider, model, currency: 'USD', scopes, policyRevision: state.revision,
        inputBound: inputTokens, outputBound: maxTokens, reservedTokens, reservedNanoUsd, price,
        usage: null, accountedTokens: 0, accountedNanoUsd: null, provenance: 'not-yet-reported',
        estimateProvenance: capped ? 'trusted-route-upper-bound' : 'uncapped-no-bound', mediaCovered: mediaCovered === true,
        sessionHash: privateId(sessionId), purpose: ['compaction', 'session-title', 'quality-review'].includes(purpose) ? purpose : 'model-call' };
      state.reservations[r.id] = r;
      audit('reserved', { receipt: r });
      return r;
    });
  }
  observe(id, raw) {
    const usage = normalizeUsage(raw);
    return this.#transaction((state, audit) => {
      const r = state.reservations[id];
      if (!r || r.status !== 'pending') fail('BUDGET_INVALID_RESERVATION');
      if (r.usage && fields.some(key => usage[key] < r.usage[key])) fail('BUDGET_USAGE_REGRESSION');
      // Usage chunks are cumulative snapshots, never additive deltas (including repeats).
      if (JSON.stringify(r.usage) === JSON.stringify(usage)) return r;
      r.usage = usage; r.provenance = 'adapter-reported-cumulative';
      addCharge(state, r, usage, usageCostNanoUsd(usage, r.price));
      audit('usage-observed', { receipt: r });
      return r;
    });
  }
  finish(id, { complete = false, reason = 'unknown', uncertain = false } = {}) {
    return this.#transaction((state, audit) => {
      const r = state.reservations[id];
      if (!r || r.status !== 'pending') fail('BUDGET_INVALID_RESERVATION');
      const input = r.usage ? r.usage.inputTokens + r.usage.cacheReadTokens + r.usage.cacheWriteTokens : 0;
      const overrun = r.usage && (input > r.inputBound || r.usage.outputTokens > r.outputBound || (r.reservedNanoUsd !== null && BigInt(r.accountedNanoUsd) > BigInt(r.reservedNanoUsd)));
      r.status = overrun ? 'overrun' : !complete || uncertain || !r.usage ? 'uncertain' : 'settled';
      r.outcome = ['stop', 'tool-calls', 'max-tokens', 'aborted', 'error', 'consumer-closed', 'invalid-usage', 'missing-finish', 'unknown'].includes(reason) ? reason : 'unknown';
      audit('request-finished', { receipt: r });
      return r;
    });
  }
  // Explicit human reconciliation of crashed/unknown/overrun calls. Never automatically releases exposure.
  reconcile({ id, usage, chargeReserved = false, acknowledgeUnknown = false }, principal) {
    this.#human(principal);
    if (typeof id !== 'string' || acknowledgeUnknown !== true || (usage !== undefined && chargeReserved)) fail('BUDGET_RECONCILE_ACK_REQUIRED');
    return this.#transaction((state, audit) => {
      const r = state.reservations[id];
      if (!r || ['settled', 'acknowledged'].includes(r.status)) fail('BUDGET_INVALID_RESERVATION');
      if (usage !== undefined) {
        const actual = normalizeUsage(usage);
        if (r.usage && fields.some(k => actual[k] < r.usage[k])) fail('BUDGET_USAGE_REGRESSION');
        addCharge(state, r, actual, usageCostNanoUsd(actual, r.price)); r.usage = actual;
        r.provenance = 'human-reconciled-provider-usage';
      } else if (chargeReserved) {
        const tokens = Math.max(r.reservedTokens, r.accountedTokens);
        const money = BigInt(r.reservedNanoUsd ?? '0') > BigInt(r.accountedNanoUsd ?? '0') ? r.reservedNanoUsd : r.accountedNanoUsd;
        addCharge(state, r, { totalTokens: tokens }, money);
        r.provenance = 'human-acknowledged-reservation-estimate-not-actual-usage';
      } else fail('BUDGET_RECONCILE_USAGE_REQUIRED');
      r.status = 'acknowledged'; audit('human-reconciled', { receipt: r }); return r;
    });
  }
  close() { this.#db.close(); }
}
